/**
 * @suppress
 */
public object FfiConverterTypeHardwareOracle: FfiConverter<HardwareOracle, Long> {
    internal val handleMap = UniffiHandleMap<HardwareOracle>()

    override fun lower(value: HardwareOracle): Long {
        if (value is HardwareOracleImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): HardwareOracle {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return HardwareOracleImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): HardwareOracle {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: HardwareOracle) = 8UL

    override fun write(value: HardwareOracle, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


