/**
 * @suppress
 */
public object FfiConverterTypeSyncPlan: FfiConverter<SyncPlan, Long> {
    override fun lower(value: SyncPlan): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): SyncPlan {
        return SyncPlan(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): SyncPlan {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: SyncPlan) = 8UL

    override fun write(value: SyncPlan, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
