/**
 * @suppress
 */
public object FfiConverterTypeVault: FfiConverter<Vault, Long> {
    override fun lower(value: Vault): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): Vault {
        return Vault(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): Vault {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: Vault) = 8UL

    override fun write(value: Vault, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



/**
 * Continuous monotonic time, including sleep; never a wall-clock timestamp.
 */
data class ClockSample (
    /**
     * Exactly 16 bytes. A verified boot identity, or a random process-wide singleton
     * shared by every oracle instance and device reopen in that process.
     */
    var `epoch`: kotlin.ByteArray
    , 
    /**
     * Monotonic milliseconds within `epoch`, including device sleep.
     */
    var `elapsedMillis`: kotlin.ULong
    
){
    

    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeClockSample: FfiConverterRustBuffer<ClockSample> {
    override fun read(buf: ByteBuffer): ClockSample {
        return ClockSample(
            FfiConverterByteArray.read(buf),
            FfiConverterULong.read(buf),
        )
    }

    override fun allocationSize(value: ClockSample) = (
            FfiConverterByteArray.allocationSize(value.`epoch`) +
            FfiConverterULong.allocationSize(value.`elapsedMillis`)
    )

    override fun write(value: ClockSample, buf: ByteBuffer) {
            FfiConverterByteArray.write(value.`epoch`, buf)
            FfiConverterULong.write(value.`elapsedMillis`, buf)
    }
}



/**
 * Result of first-time setup.
 */
data class Created (
    /**
     * Device handle.
     */
    var `device`: Device
    , 
    /**
     * Persist outside the container (Keychain ThisDeviceOnly / app-private storage).
     */
    var `sealedDeviceSecret`: kotlin.ByteArray
    , 
    /**
     * The first vault, unlocked.
     */
    var `vault`: Vault
    , 
    /**
     * Upload each to the backup folder only if no object with that name exists.
     */
    var `initialEntries`: List<NamedBlob>
    
): Disposable{
    

    

    
    @Suppress("UNNECESSARY_SAFE_CALL") // codegen is much simpler if we unconditionally emit safe calls here
    override fun destroy() {
        
    Disposable.destroy(
        this.`device`,
        this.`sealedDeviceSecret`,
        this.`vault`,
        this.`initialEntries`
    )
    }
    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeCreated: FfiConverterRustBuffer<Created> {
    override fun read(buf: ByteBuffer): Created {
        return Created(
            FfiConverterTypeDevice.read(buf),
            FfiConverterByteArray.read(buf),
            FfiConverterTypeVault.read(buf),
            FfiConverterSequenceTypeNamedBlob.read(buf),
        )
    }

    override fun allocationSize(value: Created) = (
            FfiConverterTypeDevice.allocationSize(value.`device`) +
            FfiConverterByteArray.allocationSize(value.`sealedDeviceSecret`) +
            FfiConverterTypeVault.allocationSize(value.`vault`) +
            FfiConverterSequenceTypeNamedBlob.allocationSize(value.`initialEntries`)
    )

    override fun write(value: Created, buf: ByteBuffer) {
            FfiConverterTypeDevice.write(value.`device`, buf)
            FfiConverterByteArray.write(value.`sealedDeviceSecret`, buf)
            FfiConverterTypeVault.write(value.`vault`, buf)
            FfiConverterSequenceTypeNamedBlob.write(value.`initialEntries`, buf)
    }
}



