    /**
     * `LShape` family.
     */
    L_SHAPE,
    /**
     * `UShape` family.
     */
    U_SHAPE,
    /**
     * `Square` family.
     */
    SQUARE,
    /**
     * `ZShape` family.
     */
    Z_SHAPE,
    /**
     * `NShape` family.
     */
    N_SHAPE,
    /**
     * `CShape` family.
     */
    C_SHAPE,
    /**
     * `VShape` family.
     */
    V_SHAPE,
    /**
     * `MShape` family.
     */
    M_SHAPE,
    /**
     * `WShape` family.
     */
    W_SHAPE,
    /**
     * `SShape` family.
     */
    S_SHAPE,
    /**
     * `Digit2` family.
     */
    DIGIT2,
    /**
     * `Digit7` family.
     */
    DIGIT7,
    /**
     * `JShape` family.
     */
    J_SHAPE,
    /**
     * `GShape` family.
     */
    G_SHAPE,
    /**
     * `Spiral` family.
     */
    SPIRAL,
    /**
     * `Snake` family.
     */
    SNAKE,
    /**
     * `Cross` family.
     */
    CROSS,
    /**
     * `Plus` family.
     */
    PLUS,
    /**
     * `TShape` family.
     */
    T_SHAPE,
    /**
     * `Equals` family.
     */
    EQUALS,
    /**
     * `Bars` family.
     */
    BARS;

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeBlockedShape: FfiConverterRustBuffer<BlockedShape> {
    override fun read(buf: ByteBuffer) = try {
        BlockedShape.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: BlockedShape) = 4UL

    override fun write(value: BlockedShape, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}







/**
 * Flat error. Carries no data (never names, paths or counts).
 */
sealed class HidewellException: kotlin.Exception() {
    
    /**
     * Pattern structurally invalid or below the setup policy.
     */
    class InvalidPattern(
        ) : HidewellException() {
        override val message
            get() = ""
    }
    
    /**
     * Pattern is a blocklisted common shape.
     */
    class PatternBlocklisted(
        ) : HidewellException() {
        override val message
            get() = ""
    }
    
    /**
     * Pattern already opens a vault.
     */
    class PatternInUse(
        ) : HidewellException() {
        override val message
            get() = ""
    }
    
    /**
     * No vault opens with this pattern.
     */
    class WrongPattern(
        ) : HidewellException() {
        override val message
            get() = ""
    }
    
    /**
     * Oracle: hardware key missing or invalidated.
     */
    class OracleKeyUnavailable(
        ) : HidewellException() {
        override val message
            get() = ""
    }
    
    /**
     * Oracle: device locked / authentication required.
     */
    class OracleDeviceLocked(
        ) : HidewellException() {
        override val message
            get() = ""
    }
    
    /**
     * Oracle: unexpected output.
     */
    class OracleBadOutput(
        ) : HidewellException() {
        override val message
            get() = ""
    }
    
    /**
     * Oracle: sealed device secret invalid (other device, tampered).
     */
    class OracleSealedBlobInvalid(
        ) : HidewellException() {
        override val message
            get() = ""
    }
    
    /**
     * Oracle: other failure.
     */
    class OracleFailed(
        ) : HidewellException() {
        override val message
            get() = ""
    }
    
    /**
     * Recovery phrase invalid.
     */
    class InvalidPhrase(
        ) : HidewellException() {
        override val message
            get() = ""
    }
    
    /**
     * KDF parameters invalid or below the minimum.
     */
    class InvalidParams(
        ) : HidewellException() {
        override val message
            get() = ""
    }
    
    /**
     * Authentication failed / corrupt data.
     */
    class Corrupt(
        ) : HidewellException() {
        override val message
            get() = ""
    }
    
    /**
     * Storage I/O error.
     */
    class Io(
        ) : HidewellException() {
        override val message
            get() = ""
    }
    
    /**
     * All key slots reserved.
     */
    class NoFreeSlot(
        ) : HidewellException() {
        override val message
            get() = ""
    }
    
    /**
     * Container full at the largest bucket.
     */
    class NoSpace(
        ) : HidewellException() {
        override val message
            get() = ""
    }
    
    /**
     * Not found (item, album, tag, decoy, backup object).
     */
    class NotFound(
        ) : HidewellException() {
        override val message
            get() = ""
    }
    
    /**
     * Handle locked or invalidated.
     */
    class Locked(
        ) : HidewellException() {
        override val message
            get() = ""
    }
    
    /**
     * Argument out of range.
     */
    class InvalidArgument(
        ) : HidewellException() {
        override val message
            get() = ""
    }
    
    /**
     * A foreign callback failed unexpectedly.
     */
    class CallbackFailed(
        ) : HidewellException() {
        override val message
            get() = ""
    }
    
    /**
     * Too many recent pattern attempts; wait `Device.retryAfterSeconds()`.
     */
    class RetryLater(
        ) : HidewellException() {
        override val message
            get() = ""
    }
    
    /**
     * Restore refused: that vault is already live on this device.
     */
    class VaultAlreadyPresent(
        ) : HidewellException() {
        override val message
            get() = ""
    }
    
    /**
     * A backup manifest entry is missing; refuse to restore from it.
     */
    class BackupIncomplete(
        ) : HidewellException() {
        override val message
            get() = ""
    }
    
    /**
     * This attempt hit the wipe-after-N limit; every key slot was destroyed. Returned
     * once: call `Device.erase()` and route to setup/restore.
     */
    class Wiped(
        ) : HidewellException() {
        override val message
            get() = ""
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<HidewellException> {
        override fun lift(error_buf: RustBuffer.ByValue): HidewellException = FfiConverterTypeHidewellError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeHidewellError : FfiConverterRustBuffer<HidewellException> {
    override fun read(buf: ByteBuffer): HidewellException {
        

        return when(buf.getInt()) {
            1 -> HidewellException.InvalidPattern()
            2 -> HidewellException.PatternBlocklisted()
            3 -> HidewellException.PatternInUse()
            4 -> HidewellException.WrongPattern()
            5 -> HidewellException.OracleKeyUnavailable()
            6 -> HidewellException.OracleDeviceLocked()
            7 -> HidewellException.OracleBadOutput()
            8 -> HidewellException.OracleSealedBlobInvalid()
            9 -> HidewellException.OracleFailed()
            10 -> HidewellException.InvalidPhrase()
            11 -> HidewellException.InvalidParams()
            12 -> HidewellException.Corrupt()
            13 -> HidewellException.Io()
            14 -> HidewellException.NoFreeSlot()
            15 -> HidewellException.NoSpace()
            16 -> HidewellException.NotFound()
            17 -> HidewellException.Locked()
            18 -> HidewellException.InvalidArgument()
            19 -> HidewellException.CallbackFailed()
            20 -> HidewellException.RetryLater()
            21 -> HidewellException.VaultAlreadyPresent()
            22 -> HidewellException.BackupIncomplete()
            23 -> HidewellException.Wiped()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
