                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is HidewellException.CallbackFailed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is HidewellException.RetryLater -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is HidewellException.VaultAlreadyPresent -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is HidewellException.BackupIncomplete -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is HidewellException.Wiped -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: HidewellException, buf: ByteBuffer) {
        when(value) {
            is HidewellException.InvalidPattern -> {
                buf.putInt(1)
                Unit
            }
            is HidewellException.PatternBlocklisted -> {
                buf.putInt(2)
                Unit
            }
            is HidewellException.PatternInUse -> {
                buf.putInt(3)
                Unit
            }
            is HidewellException.WrongPattern -> {
                buf.putInt(4)
                Unit
            }
