                Unit
            }
            is HidewellException.InvalidParams -> {
                buf.putInt(11)
                Unit
            }
            is HidewellException.Corrupt -> {
                buf.putInt(12)
                Unit
            }
            is HidewellException.Io -> {
                buf.putInt(13)
                Unit
            }
            is HidewellException.NoFreeSlot -> {
