/**
 * One backup operation; execute in order, stop at the first failure.
 */
sealed class SyncOp {
    
    /**
     * Upload a new immutable object (fails if it exists).
     */
    data class PutObject(
        /**
         * Name.
         */
        val `name`: kotlin.String, 
        /**
         * Bytes.
         */
        val `data`: kotlin.ByteArray) : SyncOp()
        
    {
        

        companion object
    }
    
    /**
     * Overwrite (or create) a manifest entry.
     */
    data class PutEntry(
        /**
         * Name.
         */
        val `name`: kotlin.String, 
        /**
         * Bytes.
         */
        val `data`: kotlin.ByteArray) : SyncOp()
        
    {
        

        companion object
    }
    
    /**
     * Delete an object.
     */
    data class DeleteObject(
        /**
         * Name.
         */
        val `name`: kotlin.String) : SyncOp()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeSyncOp : FfiConverterRustBuffer<SyncOp>{
    override fun read(buf: ByteBuffer): SyncOp {
        return when(buf.getInt()) {
            1 -> SyncOp.PutObject(
                FfiConverterString.read(buf),
                FfiConverterByteArray.read(buf),
                )
            2 -> SyncOp.PutEntry(
                FfiConverterString.read(buf),
                FfiConverterByteArray.read(buf),
                )
            3 -> SyncOp.DeleteObject(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: SyncOp): ULong = when(value) {
        is SyncOp.PutObject -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`name`)
                + FfiConverterByteArray.allocationSize(value.`data`)
            )
        }
        is SyncOp.PutEntry -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`name`)
                + FfiConverterByteArray.allocationSize(value.`data`)
            )
        }
        is SyncOp.DeleteObject -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`name`)
            )
        }
    }

    override fun write(value: SyncOp, buf: ByteBuffer) {
        when(value) {
            is SyncOp.PutObject -> {
                buf.putInt(1)
                FfiConverterString.write(value.`name`, buf)
                FfiConverterByteArray.write(value.`data`, buf)
                Unit
            }
            is SyncOp.PutEntry -> {
                buf.putInt(2)
                FfiConverterString.write(value.`name`, buf)
                FfiConverterByteArray.write(value.`data`, buf)
                Unit
            }
            is SyncOp.DeleteObject -> {
                buf.putInt(3)
                FfiConverterString.write(value.`name`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






/**
